import{_ as a,o as e,c as s,ak as o}from"./chunks/framework.DKi5cyCJ.js";const g=JSON.parse('{"title":"MCU 直驱步进与「插补」：现网结论与概念对照","description":"","frontmatter":{},"headers":[],"relativePath":"13_步进电机驱动与插补/00_MCU直驱与插补算法说明.md","filePath":"13_步进电机驱动与插补/00_MCU直驱与插补算法说明.md"}'),n={name:"13_步进电机驱动与插补/00_MCU直驱与插补算法说明.md"};function d(r,t,l,c,i,p){return e(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="mcu-直驱步进与「插补」-现网结论与概念对照" tabindex="-1">MCU 直驱步进与「插补」：现网结论与概念对照 <a class="header-anchor" href="#mcu-直驱步进与「插补」-现网结论与概念对照" aria-label="Permalink to &quot;MCU 直驱步进与「插补」：现网结论与概念对照&quot;">​</a></h1><blockquote><p>对照工程：<code>mechctrlinfra</code>（<code>CYHalMotorMCU</code>）· <code>mcu_framework</code>（<code>motor_speed_profile</code>）<br> 动态图：打开同目录 <a href="./插补算法动态图.html"><code>插补算法动态图.html</code></a></p></blockquote><hr><h2 id="_1-一句话结论" tabindex="-1">1. 一句话结论 <a class="header-anchor" href="#_1-一句话结论" aria-label="Permalink to &quot;1. 一句话结论&quot;">​</a></h2><p><strong>现网 MCU 直驱步进没有实现数控意义上的多轴轨迹插补（直线/圆弧/Bresenham/DDA）。</strong><br> 实现的是<strong>单轴速度表加减速</strong>（Acc → Const → Dec）：按微步推进脉冲频率，保证启停不丢步、运动时间可控。</p><p>日常口语里有人把「速度曲线插值 / 脉冲周期刷新」也叫插补，那是<strong>另一类问题</strong>；本文按数控标准语义区分二者。</p><hr><h2 id="_2-两类「插补」不要混" tabindex="-1">2. 两类「插补」不要混 <a class="header-anchor" href="#_2-两类「插补」不要混" aria-label="Permalink to &quot;2. 两类「插补」不要混&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>解决什么问题</th><th>典型算法</th><th>现网 MCU 直驱？</th></tr></thead><tbody><tr><td><strong>轨迹/路径插补</strong></td><td>多轴如何同步走出直线、圆弧、样条</td><td>Bresenham、DDA、数据采样插补</td><td><strong>无</strong></td></tr><tr><td><strong>速度/脉冲时序规划</strong></td><td>单轴如何从静止加速到巡航再减速</td><td>梯形/S 曲线、速度表查表</td><td><strong>有</strong>（速度表 Acc/Const/Dec）</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>路径插补（多轴）：   目标路径 → 每个插补周期算出各轴 Δpulse → 各轴发脉冲</span></span>
<span class="line"><span>单轴速度规划（现网）：目标步数 → 速度表算 Acc/Const/Dec → TIM 改 ARR → 逐脉冲发 STEP</span></span></code></pre></div><hr><h2 id="_3-现网-mcu-直驱实际在做什么" tabindex="-1">3. 现网 MCU 直驱实际在做什么 <a class="header-anchor" href="#_3-现网-mcu-直驱实际在做什么" aria-label="Permalink to &quot;3. 现网 MCU 直驱实际在做什么&quot;">​</a></h2><h3 id="_3-1-硬件路径" tabindex="-1">3.1 硬件路径 <a class="header-anchor" href="#_3-1-硬件路径" aria-label="Permalink to &quot;3.1 硬件路径&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应用命令（相对步数 / 找零 / 坐标）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>CYHalMotorMCU / mfw motor HAL</span></span>
<span class="line"><span>        ↓  CalcMoveSpeed / mfw_motor_speed_calc</span></span>
<span class="line"><span>速度表 + 相位机（预加速 / 加速 / 匀速 / 减速）</span></span>
<span class="line"><span>        ↓  每微步 ISR</span></span>
<span class="line"><span>TIM 更新 ARR（边沿周期）→ STEP 引脚脉冲 → DRV8711 → 电机</span></span></code></pre></div><p>锚点：</p><table tabindex="0"><thead><tr><th>层</th><th>路径</th></tr></thead><tbody><tr><td>旧工程</td><td><code>mechctrlinfra/driver/implement/mcu/cyhalmotormcu.cpp</code></td></tr><tr><td>新框架</td><td><code>mcu_framework/src/hal/mcu/motor_speed_profile.c</code>、<code>hal_motor_stm32.c</code></td></tr></tbody></table><h3 id="_3-2-速度表加减速-不是路径插补" tabindex="-1">3.2 速度表加减速（不是路径插补） <a class="header-anchor" href="#_3-2-速度表加减速-不是路径插补" aria-label="Permalink to &quot;3.2 速度表加减速（不是路径插补）&quot;">​</a></h3><ul><li>表长度约 60 档，表值近似<strong>微步速率 pps</strong>。</li><li>边沿周期：<code>us ≈ 1e6 / (pps × step_length)</code>（<code>step_length</code> 默认 2：每 2 微步才升/降一档）。</li><li>相位：<code>PRE_ACC → ACC → CONST → DEC → STOPPED</code>。</li><li>短行程会自动裁剪加速/减速段，避免步数不够仍硬加速。</li></ul><p>这是<strong>时间轴上的速度规划</strong>，输出仍是<strong>一根轴的脉冲串</strong>；没有「同时给 X、Y 分配脉冲以贴合直线」的逻辑。</p><h3 id="_3-3-多电机如何协调" tabindex="-1">3.3 多电机如何协调 <a class="header-anchor" href="#_3-3-多电机如何协调" aria-label="Permalink to &quot;3.3 多电机如何协调&quot;">​</a></h3><p>现网多电机通常是：</p><ul><li><strong>命令级串行/并行</strong>：时序脚本或协议先后发各轴运动；</li><li><strong>各轴独立 TIM</strong>：各自 Acc/Const/Dec；</li><li><strong>无公共插补周期</strong>把多轴捆成一条几何轨迹。</li></ul><p>因此「推手与皮带同时动」属于调度层并行，<strong>不等于</strong>路径插补。</p><hr><h2 id="_4-什么情况下才需要真正的插补算法" tabindex="-1">4. 什么情况下才需要真正的插补算法 <a class="header-anchor" href="#_4-什么情况下才需要真正的插补算法" aria-label="Permalink to &quot;4. 什么情况下才需要真正的插补算法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>为何需要路径插补</th></tr></thead><tbody><tr><td>平面直线插补（X+Y 同时到点且走直线）</td><td>必须按比例分配两轴脉冲，否则走折线</td></tr><tr><td>圆弧/螺旋</td><td>每周期按角度增量算两轴 Δstep</td></tr><tr><td>多轴联动轮廓（激光、点胶、雕刻）</td><td>路径精度与速度耦合</td></tr><tr><td>电子凸轮 / 主从同步</td><td>从轴位置是主轴的函数</td></tr></tbody></table><p><strong>iS20 机械控制板当前模型</strong>以「单机构单轴运动指令」为主（直线推手、盘旋转找初始等），几何轨迹在机构设计里已简化为单自由度，故 MCU 层不做路径插补是合理裁剪。</p><p>若未来出现「两轴在平面内走出指定直线/圆弧」，才应新增插补模块（建议独立于现有 <code>motor_speed_profile</code>）。</p><hr><h2 id="_5-路径插补如何实现-通用原理-供对照" tabindex="-1">5. 路径插补如何实现（通用原理，供对照） <a class="header-anchor" href="#_5-路径插补如何实现-通用原理-供对照" aria-label="Permalink to &quot;5. 路径插补如何实现（通用原理，供对照）&quot;">​</a></h2><p>以下为行业常见做法，<strong>不是现网代码</strong>。</p><h3 id="_5-1-脉冲当量与插补周期" tabindex="-1">5.1 脉冲当量与插补周期 <a class="header-anchor" href="#_5-1-脉冲当量与插补周期" aria-label="Permalink to &quot;5.1 脉冲当量与插补周期&quot;">​</a></h3><ul><li>把目标路径离散成周期 <code>T</code>（如 1 ms）内的微小线段；</li><li>每周期算出各轴应发脉冲数 <code>ΔN_i</code>；</li><li>轴内再用定时器把 <code>ΔN_i</code> 摊成均匀/加减速脉冲。</li></ul><h3 id="_5-2-bresenham-直线-整数友好" tabindex="-1">5.2 Bresenham（直线，整数友好） <a class="header-anchor" href="#_5-2-bresenham-直线-整数友好" aria-label="Permalink to &quot;5.2 Bresenham（直线，整数友好）&quot;">​</a></h3><p>以二维为例，从 <code>(0,0)</code> 到 <code>(Dx, Dy)</code> 且 <code>|Dx| ≥ |Dy|</code>：</p><ol><li>误差项 <code>e = 2·Dy − Dx</code>；</li><li>每步 X 必走 1；若 <code>e ≥ 0</code> 则 Y 也走 1，并 <code>e -= 2·Dx</code>；</li><li>每步 <code>e += 2·Dy</code>。</li></ol><p>特点：只需加减，适合 MCU；保证最接近理想直线的栅格路径。</p><h3 id="_5-3-dda-数字微分分析" tabindex="-1">5.3 DDA（数字微分分析） <a class="header-anchor" href="#_5-3-dda-数字微分分析" aria-label="Permalink to &quot;5.3 DDA（数字微分分析）&quot;">​</a></h3><p>每周期：<code>x += Dx/N</code>，<code>y += Dy/N</code>，取整后与上次位置差得到脉冲。实现简单，浮点/定点数需注意累积误差。</p><h3 id="_5-4-与现网速度表的叠加关系" tabindex="-1">5.4 与现网速度表的叠加关系 <a class="header-anchor" href="#_5-4-与现网速度表的叠加关系" aria-label="Permalink to &quot;5.4 与现网速度表的叠加关系&quot;">​</a></h3><p>真正量产轮廓控制通常是两层：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>路径插补器（多轴 ΔN） → 各轴速度/加减速整形 → 脉冲发生器</span></span></code></pre></div><p>现网只有右侧两层中的「单轴速度表 + TIM」，没有左侧路径插补器。</p><hr><h2 id="_6-和现网代码的对应关系-避免误读" tabindex="-1">6. 和现网代码的对应关系（避免误读） <a class="header-anchor" href="#_6-和现网代码的对应关系-避免误读" aria-label="Permalink to &quot;6. 和现网代码的对应关系（避免误读）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>代码现象</th><th>正确理解</th></tr></thead><tbody><tr><td><code>CalcMoveSpeed</code> / <code>mfw_motor_speed_calc</code></td><td>按总步数切 Acc/Const/Dec</td></tr><tr><td>ISR 里改 TIM 周期</td><td>刷新<strong>单轴</strong>脉冲频率</td></tr><tr><td>多个 <code>CYHalMotorMCU</code> 实例</td><td>多轴<strong>独立</strong>驱动，非联动插补</td></tr><tr><td>盘电机工位计算 <code>CalcMoveSteps</code></td><td><strong>几何换算成步数</strong>，仍是单轴一次运动</td></tr></tbody></table><hr><h2 id="_7-阅读建议" tabindex="-1">7. 阅读建议 <a class="header-anchor" href="#_7-阅读建议" aria-label="Permalink to &quot;7. 阅读建议&quot;">​</a></h2><ol><li>先打开 <a href="./插补算法动态图.html"><code>插补算法动态图.html</code></a>：上排路径/单轴；中部节拍连续进给；<strong>下部前瞻</strong>（现网用不上，见 §9）。</li><li>再读 <code>mcu_framework/src/hal/mcu/motor_speed_profile.c</code> 看 Acc/Const/Dec。</li><li>需要底层脉冲细节时对照 <code>cyhalmotormcu.cpp</code> 中 STEP 上升沿与速度台阶逻辑。</li></ol><hr><h2 id="_8-用现网业务场景举例-概念推演-不改代码" tabindex="-1">8. 用现网业务场景举例（概念推演，不改代码） <a class="header-anchor" href="#_8-用现网业务场景举例-概念推演-不改代码" aria-label="Permalink to &quot;8. 用现网业务场景举例（概念推演，不改代码）&quot;">​</a></h2><p>现网常见电机类命令：<code>ExeMotorRest</code>（找零）、<code>ExeMotorMove1</code>（到坐标）、<code>ExeMotorMove3</code>（相对步数）、盘 <code>ExeRandom_Rotate</code> / goto 工位（内部 <code>CalcMoveSteps</code>）。<br> 下面用这些真实业务说明：<strong>现在怎么走</strong>、<strong>什么时候才谈得上插补</strong>、<strong>若要插补会怎样算</strong>。</p><h3 id="_8-1-场景-a-盘转到指定工位-现网常态-——-不需要路径插补" tabindex="-1">8.1 场景 A：盘转到指定工位（现网常态 —— 不需要路径插补） <a class="header-anchor" href="#_8-1-场景-a-盘转到指定工位-现网常态-——-不需要路径插补" aria-label="Permalink to &quot;8.1 场景 A：盘转到指定工位（现网常态 —— 不需要路径插补）&quot;">​</a></h3><p><strong>业务</strong>：试剂/样本盘从当前孔转到目标孔（如孔 3 → 孔 11）。</p><p><strong>现网做法（概念）</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标工位 ID</span></span>
<span class="line"><span>  → CalcMoveSteps：按孔距、圈数、定位偏移算出「这一轴要走多少微步」</span></span>
<span class="line"><span>  → 单轴 Acc→Const→Dec 发脉冲</span></span>
<span class="line"><span>  → 到位</span></span></code></pre></div><p>这是<strong>一维圆周上的点到点</strong>。几何只出现在「步数换算」里，运动过程中只有<strong>一根旋转轴</strong>在动，没有第二轴要跟它凑成直线/圆弧轨迹。<br> → <strong>算工位 ≠ 做插补</strong>；插补器用不上。</p><h3 id="_8-2-场景-b-直线推手到坐标-盘同时转-现网常见并行-——-仍不是路径插补" tabindex="-1">8.2 场景 B：直线推手到坐标 + 盘同时转（现网常见并行 —— 仍不是路径插补） <a class="header-anchor" href="#_8-2-场景-b-直线推手到坐标-盘同时转-现网常见并行-——-仍不是路径插补" aria-label="Permalink to &quot;8.2 场景 B：直线推手到坐标 + 盘同时转（现网常见并行 —— 仍不是路径插补）&quot;">​</a></h3><p><strong>业务</strong>：时序里同一拍或相邻拍：推手 <code>ExeMotorMove1</code> 到坐标 C，盘 goto 工位 P（并行调度）。</p><p><strong>现网做法（概念）</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时序/中位：同时（或先后）下发两条独立运动命令</span></span>
<span class="line"><span>  推手轴：自己的步数 + 自己的速度表</span></span>
<span class="line"><span>  盘轴  ：自己的步数 + 自己的速度表</span></span>
<span class="line"><span>两轴 TIM 各自跑，互不知道对方这一微秒该不该发脉冲</span></span></code></pre></div><p>两轴可能「差不多同时结束」，但 Tip/抓手在空间中的路径是<strong>两段独立一维运动的合成</strong>，一般是折线或不可控曲线，<strong>没有</strong>「必须走出平面直线」的约束。<br> → 这是<strong>命令级并行</strong>，不是路径插补。</p><h3 id="_8-3-场景-c-假想「平面直线插补」——-才需要真正插补" tabindex="-1">8.3 场景 C：假想「平面直线插补」—— 才需要真正插补 <a class="header-anchor" href="#_8-3-场景-c-假想「平面直线插补」——-才需要真正插补" aria-label="Permalink to &quot;8.3 场景 C：假想「平面直线插补」—— 才需要真正插补&quot;">​</a></h3><p>假设未来某模块有两根直线轴 <strong>X（横移）</strong>、<strong>Z（升降）</strong>，业务要求：<br> 从取液点 A 到排液点 B，Tip <strong>必须沿斜线匀速贴近</strong>，不能先抬后移（避免撞盖/挂液）。</p><p>设脉冲当量已标定：</p><table tabindex="0"><thead><tr><th>轴</th><th>从 A 到 B 的位移</th><th>换算微步</th></tr></thead><tbody><tr><td>X</td><td>+12.0 mm</td><td><strong>Dx = 2400</strong></td></tr><tr><td>Z</td><td>+7.5 mm</td><td><strong>Dz = 1500</strong></td></tr></tbody></table><h4 id="现网若仍用「两次独立-move」-不满足斜线" tabindex="-1">现网若仍用「两次独立 Move」（不满足斜线） <a class="header-anchor" href="#现网若仍用「两次独立-move」-不满足斜线" aria-label="Permalink to &quot;现网若仍用「两次独立 Move」（不满足斜线）&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先 Move X 2400 步（Acc/Const/Dec）→ 再 Move Z 1500 步</span></span>
<span class="line"><span>或两命令并行：各跑各的速度表</span></span></code></pre></div><p>空间轨迹是「折线」或「两轴互不等比的曲线」，<strong>不是</strong>直线 AB。</p><h4 id="若用-bresenham-直线插补-概念步骤" tabindex="-1">若用 Bresenham 直线插补（概念步骤） <a class="header-anchor" href="#若用-bresenham-直线插补-概念步骤" aria-label="Permalink to &quot;若用 Bresenham 直线插补（概念步骤）&quot;">​</a></h4><p>目标：整段过程中始终近似满足 <code>Δz / Δx ≈ 1500/2400 = 5/8</code>。</p><ol><li><strong>选主轴</strong>：<code>|Dx| ≥ |Dz|</code> → 主轴 = X，共插补 <strong>2400</strong> 步（每步 X 必发 1 脉冲）。</li><li><strong>初始误差</strong>：<code>e = 2·Dz − Dx = 3000 − 2400 = 600</code>。</li><li><strong>每插补步</strong>（示意）： <ul><li>X 发 1 脉冲；</li><li>若 <code>e ≥ 0</code>：Z 也发 1 脉冲，且 <code>e -= 2·Dx</code>；</li><li>然后 <code>e += 2·Dz</code>。</li></ul></li><li><strong>速度层</strong>：整条斜线再套一层合成进给速度（或主轴速度表），两轴脉冲由<strong>同一个插补节拍</strong>产出，而不是两条无关的 <code>ExeMotorMove3</code>。</li></ol><p>前几步直觉（缩小比例 Dx=8, Dz=5 更容易脑算，与动态图左图同类）：</p><table tabindex="0"><thead><tr><th>步</th><th>e 判据</th><th>发脉冲</th><th>累计 (x,z)</th></tr></thead><tbody><tr><td>1</td><td>e≥0 → Z 动</td><td>ΔX=1, ΔZ=1</td><td>(1,1)</td></tr><tr><td>2</td><td>…</td><td>ΔX=1, ΔZ=0 或 1</td><td>…</td></tr><tr><td>…</td><td>共 8 步后</td><td></td><td>(8,5)</td></tr></tbody></table><p>真实 2400/1500 只是把上表拉长，算法相同。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>路径插补器（每 T 或每主轴步）</span></span>
<span class="line"><span>    → 本步 ΔNx、ΔNz</span></span>
<span class="line"><span>    → X/Z 脉冲发生器（仍可带加减速整形）</span></span></code></pre></div><p>这才是「业务上要做插补」时的做法；<strong>与现网盘 goto、单轴 Move1/Move3 是不同一层</strong>。</p><h3 id="_8-4-场景-d-盘上的「圆弧」要不要插补" tabindex="-1">8.4 场景 D：盘上的「圆弧」要不要插补？ <a class="header-anchor" href="#_8-4-场景-d-盘上的「圆弧」要不要插补" aria-label="Permalink to &quot;8.4 场景 D：盘上的「圆弧」要不要插补？&quot;">​</a></h3><p>盘电机转到下一孔，物理上走过一段圆弧，但控制上只有 <strong>θ 一维</strong>（步数 = 角度 × 传动比）。<br> 数控里的「圆弧插补」是 <strong>X+Y 两轴</strong>去逼近圆弧；你们盘是<strong>单轴旋转机构</strong>，不需要把圆弧再拆成两轴脉冲。<br> → <strong>走圆弧形轨迹的机构 ≠ 软件圆弧插补</strong>。</p><h3 id="_8-5-对照小结-对着现网命令看" tabindex="-1">8.5 对照小结（对着现网命令看） <a class="header-anchor" href="#_8-5-对照小结-对着现网命令看" aria-label="Permalink to &quot;8.5 对照小结（对着现网命令看）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>业务</th><th>典型命令/逻辑</th><th>要路径插补吗？</th></tr></thead><tbody><tr><td>推手到坐标 / 相对步进</td><td>Move1 / Move3</td><td>否（单轴点到点 + 速度表）</td></tr><tr><td>盘到工位 / 旋转</td><td><code>CalcMoveSteps</code> + 单轴运动</td><td>否（一维圆周点到点）</td></tr><tr><td>推手与盘「一起动」</td><td>时序并行两条命令</td><td>否（并行，非联动轨迹）</td></tr><tr><td>两直线轴必须走出斜线/平面直线</td><td>（现网无此产品约束）</td><td><strong>是</strong>（Bresenham/DDA 等）</td></tr><tr><td>平面圆弧、复杂轮廓</td><td>（现网无）</td><td><strong>是</strong></td></tr></tbody></table><p><strong>落地判断句</strong>：只有当产品说「两个（及以上）自由度在运动过程中必须满足几何比例/曲线」，才上插补；现网 iS20 机械控制以单自由度机构 + 命令并行为主，所以 MCU 直驱停在速度表即可。</p><h3 id="_8-6-插补节拍与速度-不是「每拍发完就停」" tabindex="-1">8.6 插补节拍与速度：不是「每拍发完就停」 <a class="header-anchor" href="#_8-6-插补节拍与速度-不是「每拍发完就停」" aria-label="Permalink to &quot;8.6 插补节拍与速度：不是「每拍发完就停」&quot;">​</a></h3><p>常见疑问：坐标下发后按节拍算 ΔN，若每拍只走 2 步，速度是不是上不去？是不是等于发了 N 条短 Move？</p><p><strong>不是。</strong> 节拍只负责「这一小段时间各轴该分多少脉冲」；整段轨迹共用<strong>一条进给速度曲线</strong>，前后节拍的脉冲在时间上首尾相接。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一条运动命令（一个目标 / 一段路径）</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  进给速度规划（整段 Acc→Const→Dec，只做一次）</span></span>
<span class="line"><span>        │  每个插补周期 T 给出本拍合成进给 F(t)</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  路径插补（按比例拆成 ΔNx、ΔNz …）</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  脉冲发生器连续输出（拍与拍之间不断流）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>对比</th><th>N 条短 Move</th><th>插补 + 一条速度曲线</th></tr></thead><tbody><tr><td>启停</td><td>每条都可能 Acc/Dec</td><td>整段只加减速一次</td></tr><tr><td>轴间比例</td><td>难保证</td><td>每拍按几何比例分配</td></tr><tr><td>速度上限</td><td>被反复加减速拖死</td><td>由 <code>F_max</code> 与脉冲能力决定</td></tr><tr><td>体感</td><td>一顿一顿</td><td>一条连续斜线/轮廓</td></tr></tbody></table><p><strong>速度怎么上得去</strong>：若周期 <code>T=1 ms</code>，某拍 <code>ΔN=20</code>，则该拍平均约 <code>20000 pps</code>；下一拍继续发，不回到 0。加减速作用在<strong>整段路径的进给 F(t)</strong> 上，不是作用在「每一拍单独一条命令」上。</p><hr><h2 id="_9-前瞻算法-look-ahead-——概念说明-现网用不上" tabindex="-1">9. 前瞻算法（Look-ahead）——概念说明（现网用不上） <a class="header-anchor" href="#_9-前瞻算法-look-ahead-——概念说明-现网用不上" aria-label="Permalink to &quot;9. 前瞻算法（Look-ahead）——概念说明（现网用不上）&quot;">​</a></h2><blockquote><p>动态图：同目录 HTML <strong>「前瞻」</strong> 一节。本节只作认知对照，<strong>不要求、也不计划在现网 MCU 直驱落地实现</strong>。</p></blockquote><h3 id="_9-1-它解决什么问题" tabindex="-1">9.1 它解决什么问题 <a class="header-anchor" href="#_9-1-它解决什么问题" aria-label="Permalink to &quot;9.1 它解决什么问题&quot;">​</a></h3><p>插补解决的是：<strong>一段几何路径</strong>里，多轴每拍如何分脉冲。<br> 前瞻解决的是：<strong>很多段路径首尾相接</strong>时，拐角处要不要每次减速到 0。</p><p>典型场景：雕刻/点胶连续折线 <code>A→B→C→D</code>。</p><table tabindex="0"><thead><tr><th>做法</th><th>拐角行为</th><th>后果</th></tr></thead><tbody><tr><td><strong>无前瞻</strong></td><td>每段独立 Acc→Const→Dec，到 B、C 都刹到 0 再启动</td><td>安全但极慢、顿挫</td></tr><tr><td><strong>有前瞻</strong></td><td>提前看后面若干段，按转角、轴加速度上限算「拐角允许速度」<code>V_corner</code>，段与段速度衔接</td><td>锐角仍须慢过，钝角可高速带过</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>路径缓冲：段1 | 段2 | 段3 | …</span></span>
<span class="line"><span>        ↓ 前瞻窗口（看 N 段）</span></span>
<span class="line"><span>  算各拐角 V_corner、反向推加减速衔接</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>  一条跨多段的进给曲线 F(s)  → 再交给插补节拍出 ΔN</span></span></code></pre></div><p>与「单段内一条 F(t)」（§8.6）的关系：</p><ul><li>§8.6：一段路径内部，拍与拍不断流。</li><li>前瞻：多段路径之间，也不在每个拐点强制回零（在动力学允许时）。</li></ul><h3 id="_9-2-粗略怎么算-仅概念" tabindex="-1">9.2 粗略怎么算（仅概念） <a class="header-anchor" href="#_9-2-粗略怎么算-仅概念" aria-label="Permalink to &quot;9.2 粗略怎么算（仅概念）&quot;">​</a></h3><ol><li>缓冲区内已有下一段（或下 N 段）几何。</li><li>在拐点看方向突变：转角越大，允许的 <code>V_corner</code> 越小（还受向心加速度 / 各轴 <code>a_max</code> 约束）。</li><li>从终点倒推、从起点正推，把各段速度曲线拼成连续剖面（梯形或 S 曲线的多段衔接）。</li><li>执行时仍按插补周期吐脉冲；前瞻只改<strong>速度规划</strong>，不改几何插补本身。</li></ol><h3 id="_9-3-和现网业务的对照-——-为何用不上" tabindex="-1">9.3 和现网业务的对照 —— 为何用不上 <a class="header-anchor" href="#_9-3-和现网业务的对照-——-为何用不上" aria-label="Permalink to &quot;9.3 和现网业务的对照 —— 为何用不上&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现网形态</th><th>为何不需要前瞻</th></tr></thead><tbody><tr><td>一条 <code>Move1</code> / <code>Move3</code> / 盘 goto</td><td><strong>单段点到点</strong>，段末本来就要停稳到位</td></tr><tr><td>时序里多条电机命令</td><td>命令之间常有业务等待（吸液、读传感器），不是连续轮廓切削</td></tr><tr><td>无「连续折线/多段 G 代码」缓冲</td><td>没有「下一段路径」可前瞻</td></tr></tbody></table><p><strong>结论</strong>：前瞻是连续轨迹数控的配套；现网是单段到达 + 业务节拍，<strong>保持现状即可</strong>。仅当未来出现「MCU 连续执行一长串折线/样条且不允许段段停稳」时，才在插补之上再谈前瞻。</p><h3 id="_9-4-三层概念速记" tabindex="-1">9.4 三层概念速记 <a class="header-anchor" href="#_9-4-三层概念速记" aria-label="Permalink to &quot;9.4 三层概念速记&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 路径插补     —— 多轴如何按几何比例发脉冲（现网：无）</span></span>
<span class="line"><span>② 单段速度规划 —— Acc/Const/Dec 或进给 F(t)（现网：有，单轴速度表）</span></span>
<span class="line"><span>③ 多段前瞻     —— 段间接力、拐角限速（现网：用不上）</span></span></code></pre></div><hr><h2 id="_10-维护" tabindex="-1">10. 维护 <a class="header-anchor" href="#_10-维护" aria-label="Permalink to &quot;10. 维护&quot;">​</a></h2><ul><li>本文描述现网 <strong>MCU 直驱</strong> 边界；FPGA 电机路径不在此列。</li><li>插补 / 前瞻均为概念资料；落地实现前需单独设计评审。</li><li>若后续引入多轴插补，应新增 <code>docs</code>/<code>src</code> 模块并在本夹追加专章；前瞻仅在「多段连续轨迹」成立后再议。</li></ul>`,108)])])}const b=a(n,[["render",d]]);export{g as __pageData,b as default};
